def split_array(nums, k):
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        cap = (lo + hi) // 2
        need, load = 1, 0
        for w in nums:
            if load + w > cap:
                need += 1
                load = 0
            load += w
        if need <= k:
            hi = cap
        else:
            lo = cap + 1
    return lo

