long long splitArray(vector<int>& a, int k) {
    long long lo = *max_element(a.begin(), a.end()), hi = 0; for (int x : a) hi += x;
    while (lo < hi) {
        long long cap = (lo + hi) / 2, load = 0; int need = 1;
        for (int x : a) { if (load + x > cap) { need++; load = 0; } load += x; }
        if (need <= k) hi = cap; else lo = cap + 1;
    }
    return lo;
}
